local _, P = ...
local Macros = P.NS.Macros
local Data = { items = {} }
Macros.ConsumableData = Data

local function Add(kind, ids, conjured, recovery)
    for rank, id in ipairs(ids) do
        Data.items[id] = { kind = kind, rank = rank, conjured = conjured, recovery = recovery }
    end
end

-- Item identities shared with the current client consumable families. Selection
