Data.subclasses = { [3] = "flask", [7] = "bandage" }
Data.retail, Data.forever = {}, {}

-- Reviewed item identities and nominal recovery amounts, 2026-10-31.
-- Values describe game data; live inventory, usability and cooldowns are checked separately.
local function Facts(target, rows)
    for _, row in ipairs(rows) do
        local flags = row[5]
        target[row[1]] = { kind = row[2], power = row[3], percent = row[4],
            conjured = flags % 2 == 1, recovery = math.floor(flags / 2) % 2 == 1 }
    end
end

